          if recursionStack.contains(subGroup) {
            return true
          } else if !visited.contains(subGroup), hasCycleFromGroup(subGroup) {
            return true
          }
        }
      }
      recursionStack.remove(group)
      return false
    }

    for group in subGroups.keys {
      if !visited.contains(group), hasCycleFromGroup(group) {
        return true
      }
    }
    return false
  }
}
}

